final_template:
AWSTemplateFormatVersion: 2010-09-09
Description: IoT Core policy for device onboarding using Lambda-backed custom resource (Node.js 24.x)
Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DeviceOnboardingPolicy
    Description: Prefix for the IoT policy name
Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: 2012-10-17
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTDevicePolicyManagement
          PolicyDocument:
            Version: 2012-10-17
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                Resource: !Sub arn:aws:iot:${AWS::Region}:${AWS::AccountId}:policy/${PolicyNamePrefix}*
  PolicyCreatorFunction:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Runtime: nodejs24.x
      Timeout: 30
      Code:
        ZipFile: |
          const https = require('https');
          const AWS = require('aws-sdk');
          const iot = new AWS.Iot({ region: process.env.AWS_REGION });

          function sendResponse(event, context, responseStatus, responseData, physicalResourceId) {
            return new Promise((resolve, reject) => {
              const responseBody = JSON.stringify({
                Status: responseStatus,
                Reason: responseData.Reason || 'See CloudWatch Logs',
                PhysicalResourceId: physicalResourceId || context.logStreamName,
                StackId: event.StackId,
                RequestId: event.RequestId,
                LogicalResourceId: event.LogicalResourceId,
                Data: responseData
              });
              const parsedUrl = new URL(event.ResponseURL);
              const options = {
                hostname: parsedUrl.hostname,
                path: parsedUrl.pathname + parsedUrl.search,
                method: 'PUT',
                headers: {
                  'Content-Type': '',
                  'Content-Length': Buffer.byteLength(responseBody)
                }
              };
              const req = https.request(options, (res) => {
                console.log('Status code: ' + res.statusCode);
                resolve();
              });
              req.on('error', (err) => {
                console.error(err);
                reject(err);
              });
              req.write(responseBody);
              req.end();
            });
          }

          function generatePolicyDocument(accountId, region) {
            // Use string concatenation to preserve literal ${iot:...} variables
            var policy = {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: "iot:Connect",
                  Resource: "arn:aws:iot:" + region + ":" + accountId + ":client/${iot:ClientId}"
                },
                {
                  Effect: "Allow",
                  Action: "iot:Publish",
                  Resource: "arn:aws:iot:" + region + ":" + accountId + ":topic/${iot:ThingName}/*"
                },
                {
                  Effect: "Allow",
                  Action: "iot:Subscribe",
                  Resource: "arn:aws:iot:" + region + ":" + accountId + ":topicfilter/${iot:ThingName}/*"
                },
                {
                  Effect: "Allow",
                  Action: "iot:Receive",
                  Resource: "arn:aws:iot:" + region + ":" + accountId + ":topic/${iot:ThingName}/*"
                }
              ]
            };
            return JSON.stringify(policy);
          }

          exports.handler = async (event, context) => {
            try {
              const requestType = event.RequestType;
              const props = event.ResourceProperties;
              const prefix = props.PolicyNamePrefix || 'DeviceOnboardingPolicy';
              const region = process.env.AWS_REGION;
              const accountId = event.StackId.split(':')[4];
              const policyDocument = generatePolicyDocument(accountId, region);
              let physicalResourceId = event.PhysicalResourceId;
              let responseData = {};

              if (requestType === 'Create') {
                const timestamp = Date.now().toString(36);
                const random = Math.random().toString(36).substring(2, 8);
                const policyName = prefix + '-' + timestamp + '-' + random;
                await iot.createPolicy({ policyName: policyName, policyDocument: policyDocument }).promise();
                physicalResourceId = policyName;
                responseData = { PolicyName: policyName };
              } else if (requestType === 'Update') {
                if (physicalResourceId) {
                  try {
                    await iot.deletePolicy({ policyName: physicalResourceId }).promise();
                  } catch (err) {
                    if (err.code !== 'ResourceNotFoundException') throw err;
                  }
                }
                const timestamp = Date.now().toString(36);
                const random = Math.random().toString(36).substring(2, 8);
                const policyName = prefix + '-' + timestamp + '-' + random;
                await iot.createPolicy({ policyName: policyName, policyDocument: policyDocument }).promise();
                physicalResourceId = policyName;
                responseData = { PolicyName: policyName };
              } else if (requestType === 'Delete') {
                if (physicalResourceId) {
                  try {
                    await iot.deletePolicy({ policyName: physicalResourceId }).promise();
                  } catch (err) {
                    if (err.code !== 'ResourceNotFoundException') throw err;
                  }
                }
                physicalResourceId = event.PhysicalResourceId;
                responseData = {};
              }

              await sendResponse(event, context, 'SUCCESS', responseData, physicalResourceId);
            } catch (err) {
              console.error(err);
              await sendResponse(event, context, 'FAILED', { Reason: err.message }, event.PhysicalResourceId);
            }
          };
  LambdaInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref PolicyCreatorFunction
      Principal: cloudformation.amazonaws.com
      SourceArn: !Sub arn:aws:cloudformation:${AWS::Region}:${AWS::AccountId}:stack/${AWS::StackName}/*
  CustomResourcePolicy:
    Type: AWS::CloudFormation::CustomResource
    DependsOn: LambdaInvokePermission
    Properties:
      ServiceToken: !GetAtt PolicyCreatorFunction.Arn
      PolicyNamePrefix: !Ref PolicyNamePrefix
Outputs:
  PolicyName:
    Description: Name of the IoT policy created for device onboarding
    Value: !GetAtt CustomResourcePolicy.PolicyName

AWSTemplateFormatVersion: '2010-09-09'
Description: Creates an Amazon Verified Permissions policy store for a Bookstore application with Cedar schema and static policies, using a custom resource to define the schema.
Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AVPWriteSchema
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - verifiedpermissions:PutSchema
                Resource: !Sub 'arn:aws:verifiedpermissions:${AWS::Region}:${AWS::AccountId}:policy-store/*'
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
  SchemaFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: python3.12
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          import json
          import time
          import logging
          import cfnresponse
          import boto3

          logger = logging.getLogger()
          logger.setLevel(logging.INFO)

          SCHEMA = {
              "Bookstore": {
                  "entityTypes": {
                      "Role": {
                          "shape": {
                              "type": "Record",
                              "attributes": {}
                          }
                      },
                      "User": {
                          "shape": {
                              "type": "Record",
                              "attributes": {
                                  "years_as_member": {
                                      "type": "Long"
                                  },
                                  "role": {
                                      "type": "Entity",
                                      "name": "Bookstore::Role"
                                  }
                              }
                          }
                      },
                      "Book": {
                          "shape": {
                              "type": "Record",
                              "attributes": {
                                  "owner": {
                                      "type": "Entity",
                                      "name": "Bookstore::User"
                                  }
                              }
                          }
                      }
                  },
                  "actions": {
                      "View": {
                          "appliesTo": {
                              "principalTypes": ["User"],
                              "resourceTypes": ["Book"]
                          },
                          "memberOf": [],
                          "context": {
                              "region": {
                                  "type": "String"
                              }
                          }
                      },
                      "ViewWithPremiumOffers": {
                          "appliesTo": {
                              "principalTypes": ["User"],
                              "resourceTypes": ["Book"]
                          },
                          "memberOf": [],
                          "context": {
                              "region": {
                                  "type": "String"
                              }
                          }
                      }
                  }
              }
          }

          def handler(event, context):
              logger.info("Received event: %s", json.dumps(event))
              response_status = cfnresponse.SUCCESS
              response_data = {}
              physical_resource_id = event.get('PhysicalResourceId', event['ResourceProperties']['PolicyStoreId'])
              try:
                  if event['RequestType'] in ['Create', 'Update']:
                      avp = boto3.client('verifiedpermissions')
                      policy_store_id = event['ResourceProperties']['PolicyStoreId']
                      # Wait for policy store to be active
                      time.sleep(10)
                      avp.put_schema(
                          policyStoreId=policy_store_id,
                          definition={
                              'value': json.dumps(SCHEMA),
                              'format': 'JSON'
                          }
                      )
                      logger.info("Schema put successfully")
                      physical_resource_id = policy_store_id
                  elif event['RequestType'] == 'Delete':
                      pass
              except Exception as e:
                  logger.error("Error: %s", str(e))
                  response_status = cfnresponse.FAILED
                  response_data['Error'] = str(e)
              cfnresponse.send(event, context, response_status, response_data, physical_resource_id=physical_resource_id)
      Timeout: 60
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
  SchemaCustomResource:
    Type: Custom::AVPSchema
    Properties:
      ServiceToken: !GetAtt SchemaFunction.Arn
      PolicyStoreId: !Ref BookstorePolicyStore
  PermitAdminView:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (
              principal is Bookstore::User,
              action == Bookstore::Action::"View",
              resource is Bookstore::Book
            )
            when {
              principal.role == Bookstore::Role::"Admin"
            };
  ForbidSpecificAdminView:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (
              principal == Bookstore::User::"AdminUser",
              action == Bookstore::Action::"View",
              resource
            );
  PermitPublisherViewOwn:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (
              principal is Bookstore::User,
              action == Bookstore::Action::"View",
              resource is Bookstore::Book
            )
            when {
              principal.role == Bookstore::Role::"Publisher" &&
              resource.owner == principal
            };
  PermitSpecificUserViewSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (
              principal == Bookstore::User::"SpecificUser",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"SpecificBook"
            );
  PermitCustomerPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (
              principal is Bookstore::User,
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource is Bookstore::Book
            )
            when {
              principal.role == Bookstore::Role::"Customer" &&
              principal.years_as_member >= 2
            };
  ForbidCustomerPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (
              principal is Bookstore::User,
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource is Bookstore::Book
            )
            when {
              principal.role == Bookstore::Role::"Customer" &&
              principal.years_as_member < 2
            };
  ForbidNonUSRegion:
    Type: AWS::VerifiedPermissions::Policy
    DependsOn: SchemaCustomResource
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            when {
              context.region != "US"
            };
  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Policy Store ID for Bookstore application
Outputs:
  PolicyStoreId:
    Description: Policy Store ID
    Value: !Ref BookstorePolicyStore

AWSTemplateFormatVersion: '2010-09-09'
Description: CloudFormation template for a Step Functions calculator demo with Lambda and IAM roles.
Parameters:
  LogRetentionDays:
    Type: Number
    Default: 3
    MinValue: 1
    MaxValue: 365
    Description: Number of days to retain logs in CloudWatch Logs.
Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      RoleName: CalculatorLambdaExecutionRole
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: !Ref LogRetentionDays
  CalculatorLambda:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: Calculator
      Runtime: nodejs22.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!operator || !operands || !Array.isArray(operands) || operands.length < 2) {
              throw new Error('Invalid input. Expected {"operator": "add|subtract|multiply|divide", "operands": [num1, num2]}');
            }
            const [a, b] = operands;
            let result;
            switch (operator) {
              case 'add':
                result = a + b;
                break;
              case 'subtract':
                result = a - b;
                break;
              case 'multiply':
                result = a * b;
                break;
              case 'divide':
                if (b === 0) {
                  throw new Error('Division by zero');
                }
                result = a / b;
                break;
              default:
                throw new Error(`Unknown operator: ${operator}`);
            }
            return { result };
          };
      Environment:
        Variables: {}
  StateMachineExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: InvokeCalculatorLambda
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt CalculatorLambda.Arn
  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineExecutionRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator state machine that routes based on operator and invokes Lambda",
          "StartAt": "CheckOperator",
          "States": {
            "CheckOperator": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "InvokeCalculator"
                }
              ],
              "Default": "UnknownOperator"
            },
            "InvokeCalculator": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorLambda.Arn}",
                "Payload.$": "$"
              },
              "ResultPath": "$.result",
              "End": true
            },
            "UnknownOperator": {
              "Type": "Fail",
              "Cause": "Unsupported operator. Supported operators: add, subtract, multiply, divide."
            }
          }
        }
Outputs:
  SampleInputFormat:
    Description: The expected input format for the Step Functions execution.
    Value: '{"operator": "add|subtract|multiply|divide", "operands": [number, number]}'
  StateMachineArn:
    Description: ARN of the Calculator state machine.
    Value: !Ref CalculatorStateMachine
  LambdaFunctionArn:
    Description: ARN of the Calculator Lambda function.
    Value: !GetAtt CalculatorLambda.Arn

AWSTemplateFormatVersion: "2010-09-09"
Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: OwnerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      BillingMode: PAY_PER_REQUEST
      TableName: TodoTable

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Scan
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |-
        type Todo {
          id: ID!
          title: String!
          owner: String
          completed: Boolean
          createdAt: AWSDateTime
        }
        input CreateTodoInput {
          title: String!
          owner: String
          completed: Boolean
        }
        input UpdateTodoInput {
          id: ID!
          title: String
          owner: String
          completed: Boolean
        }
        input DeleteTodoInput {
          id: ID!
        }
        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          queryByOwner(owner: String!): [Todo]
        }
        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }
        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoDynamoDBTable
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            id: id,
            title: ctx.arguments.input.title,
            owner: ctx.arguments.input.owner,
            completed: ctx.arguments.input.completed || false,
            createdAt: now
          };
          return {
            operation: 'PutItem',
            key: { id: { S: id } },
            attributeValues: util.dynamodb.toMapValues(item)
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          const input = ctx.arguments.input;
          const update = {};
          if (input.title !== undefined) update.title = { S: input.title };
          if (input.owner !== undefined) update.owner = { S: input.owner };
          if (input.completed !== undefined) update.completed = { BOOL: input.completed };
          const updateExpression = 'SET ' + Object.keys(update).map(k => `#${k} = :${k}`).join(', ');
          const expressionAttributeNames = {};
          const expressionAttributeValues = {};
          Object.keys(update).forEach(k => {
            expressionAttributeNames[`#${k}`] = k;
            expressionAttributeValues[`:${k}`] = update[k];
          });
          return {
            operation: 'UpdateItem',
            key: { id: { S: input.id } },
            update: { expression: updateExpression, expressionNames: expressionAttributeNames, expressionValues: expressionAttributeValues }
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: { id: { S: ctx.arguments.input.id } }
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: { id: { S: ctx.arguments.id } }
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          return { operation: 'Scan' };
        }
        export function response(ctx) {
          return ctx.result.items;
        }

  QueryByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: queryByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |-
        export function request(ctx) {
          return {
            operation: 'Query',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: { ':owner': { S: ctx.arguments.owner } }
            },
            index: 'OwnerIndex'
          };
        }
        export function response(ctx) {
          return ctx.result.items;
        }

Outputs:
  ApiEndpoint:
    Description: GraphQL API endpoint URL
    Value: !GetAtt GraphQLApi.GraphQLUrl
  ApiKeyId:
    Description: API Key ID
    Value: !Ref GraphQLApiKey
  ApiKeyValue:
    Description: API Key value
    Value: !GetAtt GraphQLApiKey.ApiKey
